//! Native EMT and Tersoff calculators against ASE (tests/golden, generated by
//! tools/golden/ase_reference.py), and their analytic Hessians against finite differences.
//!
//! This file is part of mopt-rs.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::PathBuf;

use mopt_rs::core_infra::json::JsonValue;
use mopt_rs::domain::{
    positions, Bohr, Element, EvalRequest, MolecularSystem, PeriodicCell, SpinCharge, Units,
    Vector3,
};
use mopt_rs::pes::native::{Emt, Tersoff};
use mopt_rs::pes::Calculator;

/// The Bohr radius (Angstrom) and the Hartree (eV) with which `tools/golden/ase_reference.py`
/// wrote ASE's results in atomic units (CODATA 2014, the values of mopt-rs before CODATA 2018).
const REFERENCE_BOHR_ANGSTROM: f64 = 0.52917721067;
/// See `REFERENCE_BOHR_ANGSTROM`.
const REFERENCE_HARTREE_EV: f64 = 27.21138602;

/// mopt-rs Bohr per reference Bohr.
fn length_scale() -> f64 {
    REFERENCE_BOHR_ANGSTROM / Units::BOHR_TO_ANGSTROM
}

/// mopt-rs Hartree per reference Hartree.
fn energy_scale() -> f64 {
    REFERENCE_HARTREE_EV / Units::HARTREE_TO_EV
}

fn golden(name: &str) -> JsonValue {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/golden")
        .join(name);
    JsonValue::parse(&std::fs::read_to_string(&path).unwrap()).unwrap()
}

fn floats(v: &JsonValue) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .flat_map(|x| match x.as_array() {
            Some(inner) => inner
                .iter()
                .map(|y| y.as_f64().unwrap())
                .collect::<Vec<_>>(),
            None => vec![x.as_f64().unwrap()],
        })
        .collect()
}

fn system(p: &JsonValue) -> MolecularSystem {
    let el: Vec<Element> = p
        .get("symbols")
        .unwrap()
        .as_string_vec()
        .unwrap()
        .iter()
        .map(|s| Element::parse_token(s).unwrap())
        .collect();
    // The reference geometry back in Angstrom and into mopt-rs' Bohr.
    let s = length_scale();
    let c: Vec<f64> = floats(p.get("coords_bohr").unwrap())
        .iter()
        .map(|x| x * s)
        .collect();
    let pos: Vec<[f64; 3]> = c.chunks(3).map(|r| [r[0], r[1], r[2]]).collect();
    let cell = p.get("cell_bohr").map(|cell| {
        let v: Vec<f64> = floats(cell).iter().map(|x| x * s).collect();
        let flags: Vec<bool> = p
            .get("pbc")
            .unwrap()
            .as_array()
            .unwrap()
            .iter()
            .map(|b| b.as_bool().unwrap())
            .collect();
        PeriodicCell::from_lattice_vectors(
            Vector3::<Bohr>::new([v[0], v[1], v[2]]),
            Vector3::new([v[3], v[4], v[5]]),
            Vector3::new([v[6], v[7], v[8]]),
            [flags[0], flags[1], flags[2]],
        )
        .unwrap()
    });
    MolecularSystem::new(el, &positions::<Bohr>(&pos), SpinCharge::default(), cell).unwrap()
}

fn check_against_ase(calc: &dyn Calculator, file: &str, e_tol: f64, g_tol: f64) {
    check_points(calc, &golden(file), file, e_tol, g_tol);
}

fn check_points(calc: &dyn Calculator, g: &JsonValue, file: &str, e_tol: f64, g_tol: f64) {
    for p in g.get("points").unwrap().as_array().unwrap() {
        let name = p.get("structure").unwrap().as_str().unwrap();
        let sys = system(p);
        let out = calc.evaluate(&sys, &EvalRequest::ENERGY_GRAD).unwrap();
        // The reference energy and gradient in mopt-rs' Hartree and Bohr.
        let (s, k) = (length_scale(), energy_scale());
        let e_ref = p.get("energy_hartree").unwrap().as_f64().unwrap() * k;
        let de = (out.energy.value() - e_ref).abs();
        let g_ref: Vec<f64> = floats(p.get("gradient").unwrap())
            .iter()
            .map(|g| g * k / s)
            .collect();
        let dg = out
            .gradient_bohr
            .iter()
            .zip(&g_ref)
            .fold(0.0_f64, |m, (a, b)| m.max((a - b).abs()));
        eprintln!("{file} {name}: |dE| = {de:e} Hartree, max|dg| = {dg:e} Hartree/Bohr");
        assert!(de < e_tol, "{name}: E = {} vs {e_ref}", out.energy.value());
        assert!(dg < g_tol, "{name}: gradient error {dg}");
    }
}

/// Analytic Hessian against central differences of the analytic gradient.
fn check_hessian(calc: &dyn Calculator, sys: &MolecularSystem, tol: f64) {
    let out = calc.evaluate(sys, &EvalRequest::ENERGY_GRAD_HESS).unwrap();
    let h = out.hessian_bohr.unwrap();
    let x0 = sys.coords_flat_bohr();
    let step = 1e-5;
    let mut worst = 0.0_f64;
    for k in 0..sys.dof() {
        let mut xp = x0.clone();
        let mut xm = x0.clone();
        xp[k] += step;
        xm[k] -= step;
        let gp = calc
            .evaluate(
                &sys.with_flat_coords_bohr(&xp).unwrap(),
                &EvalRequest::ENERGY_GRAD,
            )
            .unwrap()
            .gradient_bohr;
        let gm = calc
            .evaluate(
                &sys.with_flat_coords_bohr(&xm).unwrap(),
                &EvalRequest::ENERGY_GRAD,
            )
            .unwrap()
            .gradient_bohr;
        for i in 0..sys.dof() {
            worst = worst.max(((gp[i] - gm[i]) / (2.0 * step) - h[(i, k)]).abs());
            assert!((h[(i, k)] - h[(k, i)]).abs() < 1e-12);
        }
    }
    eprintln!("Hessian vs finite differences: {worst:e}");
    assert!(worst < tol, "Hessian error {worst}");
}

#[test]
fn emt_matches_ase() {
    check_against_ase(&Emt::new(), "single_point_emt.json", 1e-10, 1e-10);
}

#[test]
fn emt_hessian_is_exact() {
    let g = golden("single_point_emt.json");
    for p in g.get("points").unwrap().as_array().unwrap() {
        check_hessian(&Emt::new(), &system(p), 1e-8);
    }
}

fn tersoff_for(sys: &MolecularSystem) -> Tersoff {
    Tersoff::tersoff_1989(&sys.elements).unwrap()
}

#[test]
fn tersoff_matches_ase() {
    let g = golden("single_point_tersoff.json");
    for p in g.get("points").unwrap().as_array().unwrap() {
        let sys = system(p);
        let calc = tersoff_for(&sys);
        let one = JsonValue::Object(
            [("points".to_string(), JsonValue::Array(vec![p.clone()]))]
                .into_iter()
                .collect(),
        );
        check_points(&calc, &one, "tersoff", 1e-10, 1e-10);
    }
}

#[test]
fn tersoff_hessian_is_exact() {
    let g = golden("single_point_tersoff.json");
    for p in g.get("points").unwrap().as_array().unwrap() {
        let sys = system(p);
        check_hessian(&tersoff_for(&sys), &sys, 1e-8);
    }
}
